// === Tab: mySketch ===

// let triangle particle system.
// let and/or drag mouse to generate triangles. let any key to clear.
// particles, particle system, boolean, PVector, ArrayList, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), random, vertex, monochrome.

particleGenerator  pg;
let makeParticles;

function setup() {
  createCanvas(5760, 1080);
  //createCanvas(windowWidth, windowHeight, WEBGL);
  background(240);
  pg = new particleGenerator();
}

function draw() {
  pg.run();
}

function mousePressed() {
  makeParticles = true;
}
function mouseReleased() {
  makeParticles = false;
}


// %%%%%% Classes %%%%%%%%

class particleGenerator {
  ArrayList<Particle> particles;
  pos;

  constructor() {
    pos = new PVector();
    particles = new ArrayList<Particle>();
  }

  function run() {
    if (makeParticles) {
      pos.set((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      particles.add(new Particle(pos));
    }
    for (i = particles.size ()-1; i >= 0; i--) {
      let p = particles.get(i);
      p.run();
      if (p.isDead()) {
        particles.remove(i);
      }
    }
  }
}


class Particle {
  pos;
  vel;
  sze, mx, my, maxSze;
  angle, incr;

  constructor(p) {
    vel = new PVector(random(-2, 2), random(-2, 2));
    vel.mult(5);
    pos = p.get();
    sze = 1;
    angle  = 0;
    maxSze = random(5, 50);
    incr = 5;
    if (random(1) < 0.5) incr = -5;
    mx = random(0.3, 0.5);
    if (random(1) < 0.5) mx = -mx;
    my = random(0.3, 0.5);
    if (random(1) < 0.5) my = -my;
  }

  function run() {
    move();
    display();
  }

  function move() {
    vel.x += mx;
    vel.y += my;
    pos.add(vel);
    sze  += random(0.5, 1.5);
    angle += incr;
  }

  function display() {
    stroke(random(255),random(255),random(255));
    strokeWeight(1);
		fill(random(255),random(255),random(255));

    //call to let canvas let externals.context.shadowOffsetX = 5;
    externals.context.shadowOffsetY = 5;
    externals.context.shadowBlur = 15;
    externals.context.shadowColor = "black";

    drawTri(pos.x, pos.y, sze, angle);
  }

  isDead() {
    if (sze >=  maxSze) {
      return true;
    } else {
      return false;
    }
  }

  function drawTri(xIn, yIn, sz, ang) {
    let x, y;
    beginShape();
    for (a = ang; a < 360 + ang; a += 360/3) {
      x = xIn + cos(radians(a)) * sz;
      y = yIn + sin(radians(a)) * sz;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function keyPressed() {
  background(240);
}

